  public void dispose() {
    myDisposed = true;
    ListSequence.fromList(myGutterMessagesRebuilders).visitAll((it) -> it.dispose());
    myActionGroup.removeAll();
    myActionGroup = null;
    myMainLayout.dispose();
    myInspectorLayout.dispose();
    for (ChangeGroupLayout layout : myMainChangeGroupLayouts) {
      if (layout != null) {
        layout.dispose();
      }
    }
    for (ChangeGroupLayout layout : myInspectorChangeGroupLayouts) {
      if (layout != null) {
        layout.dispose();
      }
    }
    myDiffEditorsGroup.dispose();
  }

  protected void invalidateLayouts() {
    ListSequence.fromList(myMainChangeGroupLayouts).concat(ListSequence.fromList(myInspectorChangeGroupLayouts)).where(new NotNullWhereFilter()).visitAll((b) -> b.invalidate());
  }

